import{z as l,x as o,o as s,c as d,q as t,j as A,D as e,d as E,s as i,S as n,b as B}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"VLIW 与 EPIC","description":"","frontmatter":{"title":"VLIW 与 EPIC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vliw-epic.md","filePath":"cs/vliw-epic.md","lastUpdated":1791413859000}'),p={name:"cs/vliw-epic.md"};function C(I,a,c,D,h,m){const r=o("Mermaid");return s(),d("div",null,[a[2]||(a[2]=t('<h1 id="vliw-与-epic" tabindex="-1">VLIW 与 EPIC <a class="header-anchor" href="#vliw-与-epic" aria-label="Permalink to &quot;VLIW 与 EPIC&quot;">​</a></h1><div class="epigraph"><p>超标量用硬件在运行时找独立指令；VLIW 让编译器把能同拍执行的操作打进一个长字，硬件按槽直发，不再做复杂唤醒。</p><footer>—— 据 Fisher, Very Long Instruction Word architectures；Itanium / EPIC 的公开叙述；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/flynn-taxonomy">上一课</a> 把多发射仍标成 SISD 上的 ILP。<a href="/cs/issue-queue-wakeup">发射队列</a> 的唤醒/选择限制频率。本课不重画 Flynn 格。缺口是 <strong>VLIW：并行性在编译时打包；EPIC 用谓词与投机 load 补上「编译看不见的」那部分。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>宽发射核的 IQ 与 <a href="/cs/prf-free-list">PRF</a> 很贵。若编译器已经用追踪调度把独立操作排好，硬件可以按「槽 0 ALU、槽 1 访存、槽 2 分支」直送，省掉运行时唤醒。缺口不是 SIMD 的数据并行，而是<strong>指令级并行的静态化</strong>。失败模式：二进制绑死机器宽度，cache miss 让整束停顿。</p><p><span class="marginnote">直觉类比：VLIW 束像拼车出车单——编译器提前查好哪几位乘客（操作）互不干扰，排进同一辆车的固定座位（槽 0 给 ALU、槽 1 给访存），司机（硬件）照单开车、不做任何临场配对；一趟拼错，全车人一起等。</span></p><p><span class="marginnote">Fisher 的 VLIW 来自微码宽字。Itanium 的 EPIC 加谓词执行、投机 load 与恢复，试图在通用代码上接近 VLIW 而不完全暴露槽。商业上通用负载让位于乱序核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器把最多 \\(W\\) 个操作打进 bundle，标明停顿或停顿组。硬件按 bundle 取指，译码几乎一对一到功能单元。谓词：两条方向都编码，用条件寄存器作废其中一路，少用 <a href="/cs/gshare-predictor">gshare</a>。投机 load：提前 load，若异常则推迟到使用点。</p><p><span class="marginnote">谓词执行可翻译成「两条路都算，发错再撕一张」：分支两个方向的操作都编码进代码，各自挂一个条件寄存器，硬件照算不误，条件为假的一路结果作废——用一点点多余的计算，换掉一次预测失败后的整条流水线冲刷。</span></p>',10)),(s(),A(n,null,{default:e(()=>[i(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMP%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%E6%89%93%E5%8C%85%22%5D%20--%3E%20BUNDLE%5B%22VLIW%20%E6%9D%9F%22%5D%0A%20%20BUNDLE%20--%3E%20SLOTS%5B%22%E6%8C%89%E6%A7%BD%E7%9B%B4%E5%8F%91%22%5D%0A%20%20MISS%5B%22%E4%B8%80%E6%A7%BD%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20STALL%5B%22%E6%95%B4%E6%9D%9F%E6%88%96%E5%90%8E%E7%BB%AD%E6%9D%9F%E5%81%9C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[E("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,[E("与乱序对照：ILP 窗口从 ROB 挪到编译器的追踪。对象代码随微结构宽度失效，这与 "),B("a",{href:"/cs/isa-abi-boundary"},"ISA 作为 ABI"),E(" 的「二进制稳定」紧张——EPIC 想用一层抽象缓解，仍难。DSP 与某些加速器至今用 VLIW，因为代码可控、缺失可预测。")],-1)),(s(),A(n,null,{default:e(()=>[i(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%E9%A1%BA%E5%BA%8F%E4%BB%A3%E7%A0%81%22%5D%20--%3E%20HW%5B%22%E4%B9%B1%E5%BA%8F%E6%A0%B8%3A%20%E7%A1%AC%E4%BB%B6%E8%BF%90%E8%A1%8C%E6%97%B6%E6%89%BE%E7%8B%AC%E7%AB%8B%E6%8C%87%E4%BB%A4%22%5D%0A%20%20SRC%20--%3E%20SW%5B%22VLIW%3A%20%E7%BC%96%E8%AF%91%E5%99%A8%E9%9D%99%E6%80%81%E6%89%93%E5%8C%85%22%5D%0A%20%20HW%20--%3E%20ROB%5B%22%E7%AA%97%E5%8F%A3%E5%9C%A8%20ROB%20%E4%B8%8E%E5%8F%91%E5%B0%84%E9%98%9F%E5%88%97%22%5D%0A%20%20SW%20--%3E%20TRACE%5B%22%E7%AA%97%E5%8F%A3%E5%9C%A8%E7%BC%96%E8%AF%91%E5%99%A8%E7%9A%84%E8%BF%BD%E8%B8%AA%E8%B0%83%E5%BA%A6%E8%A1%A8%22%5D%0A%20%20ROB%20--%3E%20BIN1%5B%22%E4%BA%8C%E8%BF%9B%E5%88%B6%E9%9A%8F%E6%A0%B8%E4%BB%A3%E6%8D%A2%E4%BB%8D%E5%8F%AF%E7%94%A8%22%5D%0A%20%20TRACE%20--%3E%20BIN2%5B%22%E4%BA%8C%E8%BF%9B%E5%88%B6%E7%BB%91%E6%AD%BB%E6%9C%BA%E5%99%A8%E5%AE%BD%E5%BA%A6%22%5D%0A%20%20MISS%5B%22cache%20miss%20%E5%81%9C%E9%A1%BF%22%5D%20--%3E%7C%22%E4%B9%B1%E5%BA%8F%22%7C%20CONT%5B%22%E5%85%B6%E4%BB%96%E6%9D%9F%E7%BB%A7%E7%BB%AD%E8%B7%91%22%5D%0A%20%20MISS%20--%3E%7C%22VLIW%22%7C%20STOP%5B%22%E6%95%B4%E6%9D%9F%E4%B8%80%E8%B5%B7%E5%81%9C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">常见误区：因为通用 CPU 淘汰了 VLIW 就以为它死了。DSP、基带与许多加速器至今用 VLIW——负载规则、编译器能见度高、缺槽可预测，静态打包的收益留得住；通用代码的分支与访存太野，才是乱序核赢下的原因。</span></p><p>本课只谈 CPU/DSP 指令束。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评价 Itanium 生态。下一课数据流与解耦访存：另一条「让编译器/硬件把访存与运算拆开」的路，不是长指令字。向量 lane 是 SIMD 格子，不是 VLIW 槽。</p><p>后课默认：静态打包省 IQ，但把 miss 与二进制兼容变成编译问题。把 load 与使用解耦到不同时钟域/队列，是 DAE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VLIW 把 ILP 打包交给编译器，硬件按槽发射。</li><li>EPIC 用谓词与投机 load 补通用代码；通用 CPU 仍回到乱序。</li><li>解耦访存执行是下一课另一条静态/硬件混合路。</li><li>出处：Fisher；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',7))])}const S=l(p,[["render",C]]);export{P as __pageData,S as default};
